-- Blog categories, managed by administrators. One category has many blogs (blogs.category_id).
-- Soft-deleted through deleted_at; deleting a category never touches its blogs.
-- Rollback: db/rollback/U202610251800__create_blog_categories.sql

SET LOCAL lock_timeout = '5s';

CREATE TABLE blog_categories (
    id                BIGSERIAL PRIMARY KEY,
    title             VARCHAR(255)  NOT NULL,
    -- Generated by the application from the title. Unique across soft-deleted rows too, so an old
    -- category URL never points at a different category.
    slug              VARCHAR(255)  NOT NULL,
    -- UI icon identifier (e.g. home, mdi:home-city), not a URL or path.
    icon              VARCHAR(100),
    -- Object storage key of the category image, never a public URL or client filename.
    image             TEXT,
    status            VARCHAR(20)   NOT NULL DEFAULT 'active',
    meta_title        VARCHAR(255),
    meta_description  TEXT,
    created_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    deleted_at        TIMESTAMPTZ,

    CONSTRAINT uq_blog_categories_slug UNIQUE (slug),
    CONSTRAINT chk_blog_categories_title_not_blank CHECK (btrim(title) <> ''),
    CONSTRAINT chk_blog_categories_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT chk_blog_categories_status CHECK (status IN ('active', 'inactive')),
    CONSTRAINT chk_blog_categories_icon CHECK (icon ~ '^[A-Za-z0-9][A-Za-z0-9_:-]*$'),
    -- Relative object key: no leading slash, no "..", no scheme (same rule as banners).
    CONSTRAINT chk_blog_categories_image
        CHECK (image ~ '^[A-Za-z0-9][A-Za-z0-9/_.-]*$' AND image NOT LIKE '%..%')
);

-- Public category list (active only) and admin status filter. Slug lookups use uq_blog_categories_slug.
CREATE INDEX idx_blog_categories_status ON blog_categories (status) WHERE deleted_at IS NULL;

COMMENT ON COLUMN blog_categories.slug IS 'Application-generated URL key; never reused, even after soft delete';
COMMENT ON COLUMN blog_categories.status IS 'Visibility switch; inactive categories are hidden from public lists';
COMMENT ON COLUMN blog_categories.deleted_at IS 'Soft-delete timestamp; NULL = not deleted';
